import "server-only";
import QRCode from "qrcode";

/**
 * Renders a QR code as an inline SVG string (server-side, no external image request).
 * The caller injects this into a div with dangerouslySetInnerHTML — the content is
 * entirely generated by us from a known-safe ticket token, never from user input.
 */
export async function renderQrSvg(data: string): Promise<string> {
  return QRCode.toString(data, {
    type: "svg",
    margin: 0,
    errorCorrectionLevel: "M",
    color: { dark: "#050507", light: "#00000000" },
  });
}
